/// Windowed [SessionStorage] over a byte-scanned tail of the session file
/// (issue #135): open costs O(window), not O(file).
///
/// The resident window is ANCHORED ON THE TAIL: the newest records are
/// the expensive ones to lose (they are the live conversation), so
/// appends and tail ingests only ever evict the OLDEST side. Paging
/// upward past the residency cap slides the window up instead — the
/// newest side leaves through an explicit user action ([loadOlder]) and
/// comes back through [loadNewer] (the page-down path); it can never
/// vanish silently. The session leaf ([_currentLeafId]) is the TRUE file
/// leaf regardless of what is resident — eviction never rewrites it.
///
/// The view equals the resident window: [loadOlder] returns the records
/// that joined the active branch so the caller can prepend them,
/// [loadNewer] returns the ones that rejoined at the bottom, and
/// [jumpToOffset] re-centers the window anywhere in the file. Every
/// read also feeds the sparse offset map ([offsetOf]) — record byte
/// offsets for everything explored this open — so repeat jumps skip
/// re-reads. Small sessions degenerate cleanly: when the whole file
/// fits in one chunk, the window IS the file.
library;

import 'dart:convert';

import '../compaction/token_estimation.dart';
import '../env/execution_env.dart';
import '../exceptions.dart';
import '../env/session_parse_executor.dart';
import '../session_io_retry.dart';
import 'session_chunk_reader.dart';
import 'session_record.dart';
import 'session_storage.dart';

/// Append-only session storage over a byte-scanned window of the file.
///
/// Segment boundary (gh-1077): this view is bound to the ACTIVE segment
/// (the primary file). Records archived into `<path>.part-NN` siblings
/// by segment rotation are NOT reachable through [loadOlder] — paging
/// stops at the primary's header copy and [hasOlder] goes false there,
/// by design: the chat path only ever renders recent history. Full-chain
/// reads go through [JsonlSessionStorage.open] (which loads parts +
/// primary as one chain) or `JsonlSessionRepo.readCustomRecordsOfType`.
///
/// The in-memory index holds the LOADED records only; every structure
/// (`_entries`, `_byId`, `_labelsById`, offsets) is pruned in the same
/// pass when eviction drops records, so no strong reference outlives
/// residency (issue #135 round-2 review). The branch walk
/// ([getPathToRoot]) stops silently at the window edge — records
/// outside are reachable through [loadOlder]/[loadNewer]/
/// [jumpToOffset]. Side-branch records that share a chunk with the
/// active branch enter the index for id lookups but never render: the
/// branch joins ([_joinBranchUpward]) walk the parent chain only.
final class WindowedSessionStorage
    implements SessionStorage, SessionHeaderCache {
  WindowedSessionStorage._(
    this._fs,
    this._filePath,
    this._reader,
    SessionMetadata metadata,
    SessionChunk chunk, {
    int residentRecords = defaultResidentRecords,
    int residentBytes = defaultResidentBytes,
    this._chunkRecords = defaultChunkRecords,
    this._chunkBytes = defaultChunkBytes,
    this._ioRetry = const SessionIoRetryConfig(),
  }) : _metadata = metadata,
       _hasOlder = chunk.hasOlder,
       _windowTopOffset = chunk.isEmpty ? null : chunk.firstOffset,
       _knownFileBytes = chunk.endOffset,
       _fileSize = chunk.fileSize,
       _fileMtimeMs = chunk.fileMtimeMs,
       _residentRecordCap = residentRecords,
       _residentByteCap = residentBytes {
    _indexChunk(chunk);
    _currentLeafId = chunk.entries.isEmpty
        ? null
        : leafIdAfterSessionRecord(chunk.entries.last.record);
    _branchBottomId = _currentLeafId;
  }

  /// Resident-window bounds (issue #135 AC1): memory is bounded by the
  /// cache, not the file. Defaults keep ~3 chunks alive.
  static const defaultResidentRecords = 3 * defaultChunkRecords;
  static const defaultResidentBytes = 3 * defaultChunkBytes;

  final int _residentRecordCap;
  final int _residentByteCap;

  /// Open-time chunk sizing — the STARTING block size of the
  /// [growOlderUntil] boundary walk (the walk doubles per page, so deep
  /// boundaries converge in a handful of single-read strips).
  final int _chunkRecords;
  final int _chunkBytes;

  /// While true, [_evictToBound] is a no-op — set for the duration of a
  /// [growOlderUntil] boundary walk so the newest side (the resume's
  /// tail anchor) cannot slide out mid-walk.
  bool _suspendEviction = false;

  final FileSystem _fs;
  final String _filePath;
  final SessionChunkReader _reader;

  /// Transient-ENOENT retry wiring (issue #427) for the disk appends;
  /// the reader-side page-ins stay outside the retry window.
  final SessionIoRetryConfig _ioRetry;

  final List<SessionRecord> _entries = [];

  /// File-order start offsets aligned with [_entries].
  final List<int> _offsets = [];

  /// File-order END offsets aligned with [_entries] (half-open spans
  /// [_offsets[i], _ends[i])) - the byte span of each resident record.
  final List<int> _ends = [];
  final Map<String, SessionRecord> _byId = {};
  final Map<String, String> _labelsById = {};

  /// Sparse offset map (issue #135 AC6): record id → line start offset
  /// for every record whose chunk was read THIS OPEN, evicted or not.
  /// Ints and id strings only — never a record reference — and it dies
  /// with the open (nothing persisted, nothing to invalidate).
  final Map<String, int> _offsetById = {};

  /// Records appended (or read) BELOW the window while deep-paged: the
  /// view branch still needs them reachable ([getEntry] /
  /// [getPathToRoot]) until [loadNewer] pages them in. Entries leave
  /// the moment they re-enter the window; a re-anchor clears it. Bounded
  /// by this open's own writes, not by the file (the live conversation
  /// itself is the bound — the app already holds these records in its
  /// provider context).
  final Map<String, SessionRecord> _appendedBelow = {};

  /// The TRUE session leaf: set at open, advanced by appends/ingests,
  /// reset by re-anchoring — NEVER derived from residency, so eviction
  /// cannot ride it down the file.
  String? _currentLeafId;

  /// The newest ACTIVE-BRANCH record inside the window — the bottom
  /// anchor the branch joins extend. Rides up (to its parent) only when
  /// bottom-side eviction drops it.
  String? _branchBottomId;

  final SessionMetadata _metadata;

  /// Byte offset of the oldest resident record — the [loadOlder] anchor.
  /// Rides up with oldest-side eviction; `null` only for an empty
  /// window over an empty file.
  int? _windowTopOffset;

  /// Byte offset just past the newest resident record — the
  /// [loadNewer]/ingest cursor.
  int _knownFileBytes;

  /// Last-seen file size (truncation guard, append offset math).
  int _fileSize;

  /// Last-seen mtime (same-size rewrite guard, issue #135 AC7); `0`
  /// until the first stat — never triggers a spurious re-anchor.
  int _fileMtimeMs;

  bool _hasOlder = false;
  int? _totalRecords;

  /// File records ABOVE the window (the "Load earlier" banner count),
  /// maintained incrementally; `null` = unknown (right after a jump)
  /// until an edge is walked. Never negative by construction: every
  /// transition is anchored to a byte scan, not to a stale total.
  int? _aboveCount;

  /// File records BELOW the window — what [loadNewer] reveals next
  /// (the page-down count). `null` = unknown (after a jump).
  int? _belowCount = 0;

  /// Resident-window instrumentation (issue #135 AC1: the bound is
  /// asserted by tests, not by user behavior).
  int get residentCount => _entries.length;
  int get residentWindowBytes => _residentWindowBytes;

  @override
  SessionMetadata get cachedMetadata => _metadata;

  /// Whether records may exist above the loaded window (the "more above"
  /// signal while [cachedTotalRecords] is still unknown).
  bool get hasOlder => _hasOlder || (_aboveCount ?? -1) > 0;

  /// Whether records sit below the loaded window (the "Load newer"
  /// signal — the page-down path back to the live tail).
  bool get hasNewer =>
      (_belowCount ?? (_knownFileBytes < _fileSize ? 1 : 0)) > 0;

  /// The exact record count once [countRecords] completed; `null` before —
  /// the UI shows "more above" until then.
  int? get cachedTotalRecords => _totalRecords;

  /// The byte offset of [recordId] if its chunk was ever read this open
  /// (the sparse offset map); `null` for unexplored records.
  int? offsetOf(String recordId) => _offsetById[recordId];

  /// The [SessionChunkReader] backing this window (jump support).
  SessionChunkReader get reader => _reader;

  /// Opens a session windowed: header + newest chunk only. Small sessions
  /// load completely (window == file) and behave exactly like
  /// [JsonlSessionStorage.open].
  static Future<WindowedSessionStorage> open(
    FileSystem fs,
    String filePath, {
    int chunkRecords = defaultChunkRecords,
    int chunkBytes = defaultChunkBytes,
    int? residentRecords,
    int? residentBytes,
    SessionParseExecutor? parseExecutor,
    SessionIoRetryConfig ioRetry = const SessionIoRetryConfig(),
    SessionTimingLogger? timingLog,
  }) async {
    final totalSw = Stopwatch()..start();
    var phaseSw = Stopwatch()..start();
    final reader = SessionChunkReader(
      fs: fs,
      path: filePath,
      parseExecutor: parseExecutor,
    );
    final readerMs = phaseSw.elapsedMilliseconds;
    phaseSw
      ..reset()
      ..start();
    final header = await reader.readHeader();
    final headerMs = phaseSw.elapsedMilliseconds;
    phaseSw
      ..reset()
      ..start();
    final chunk = await reader.readTail(
      maxRecords: chunkRecords,
      maxBytes: chunkBytes,
    );
    final tailMs = phaseSw.elapsedMilliseconds;
    final storage = WindowedSessionStorage._(
      fs,
      filePath,
      reader,
      headerToSessionMetadata(header, filePath),
      chunk,
      residentRecords: residentRecords ?? defaultResidentRecords,
      residentBytes: residentBytes ?? defaultResidentBytes,
      chunkRecords: chunkRecords,
      chunkBytes: chunkBytes,
      ioRetry: ioRetry,
    );
    timingLog?.call(
      'resume_timing open file=${filePath.split('/').last} mode=windowed '
      'reader_ms=$readerMs header_ms=$headerMs tail_ms=$tailMs '
      'window_records=${chunk.entries.length} file_bytes=${chunk.fileSize} '
      'has_older=${chunk.hasOlder} total_ms=${totalSw.elapsedMilliseconds}',
    );
    return storage;
  }

  /// Background record count (streams newlines, no JSON decode). The first
  /// call scans; later calls return the memo.
  Future<int> countRecords() async =>
      _totalRecords ??= await _reader.countRecords();

  /// File records above the window — the "Load earlier" banner count.
  /// `null` while unknown (background count running, or right after a
  /// [jumpToOffset] until an edge is walked); `0` at the file top.
  Future<int?> countAbove() async {
    if (_aboveCount case final known?) return known;
    if (!_hasOlder) return _aboveCount = 0;
    final below = _belowCount;
    if (below == null) return null;
    final total = await countRecords();
    return _aboveCount = total - _entries.length - below;
  }

  /// File records below the window — the "Load newer" banner count.
  /// `null` while unknown (after a [jumpToOffset]); `0` at the tail.
  int? get countBelow => _belowCount;

  /// Loads one chunk of records above the window. Returns the records
  /// that JOIN THE ACTIVE BRANCH, root-first — the transcript delta to
  /// prepend. Side-branch records in the chunk enter the index (id
  /// lookups) but are not returned. Reads chunks until a branch record
  /// lands (a chunk can be entirely foreign-branch), the branch root or
  /// file top is reached, or [maxChunks] passes. When the residency cap
  /// is exceeded the NEWEST side slides out — deep paging moves the
  /// window up; [loadNewer] (or [jumpToOffset]) brings the tail side
  /// back.
  Future<List<SessionRecord>> loadOlder({
    int maxRecords = defaultChunkRecords,
    int maxBytes = defaultChunkBytes,
    int maxChunks = 8,
  }) async {
    final joined = <SessionRecord>[];
    for (var pass = 0; pass < maxChunks; pass++) {
      final chunk = await _readOlderChunk(maxRecords, maxBytes);
      if (chunk == null) break;
      joined.addAll(_joinBranchUpward(chunk.$1, chunk.$2));
      if (joined.isNotEmpty || !_hasOlder) break;
    }
    _evictToBound(newestSide: true);
    return joined;
  }

  /// Pages older chunks until [found] matches a record on the active
  /// branch, the file top is reached, or [maxPages] pass — WITHOUT
  /// sliding the newest side out: the residency cap is suspended for the
  /// walk, so a resume keeps the tail anchored while reaching the
  /// compaction boundary (the CLI resume walks to the newest compaction
  /// — the old ensure path let [loadOlder] evict the leaf on the first
  /// chunk, the branch read empty, and every deep-boundary resume fell
  /// back to a full open: 10s+ on a marathon file).
  ///
  /// Returns whether the tail-anchored branch is intact after the walk;
  /// `false` only on [maxPages] exhaustion (the caller's documented
  /// full-open fallback). A session without a match pages everything —
  /// the whole chain is then resident and the walk reports `true`.
  ///
  /// [tokenBudget] (issue #503) adds a second stop condition: once the
  /// resident branch's estimated CONTEXT tokens reach the budget (only
  /// context-projecting records count — ledger payloads like
  /// `model_request_summary` count zero, see [estimateSessionBranchTokens]),
  /// the walk stops even without a match. A resume needs only what fits
  /// the model's context window; older history pages in lazily through
  /// the scrollback's [loadOlder] path. `null` keeps the pure
  /// match/file-head semantics.
  ///
  /// gh-1425 (AC1, replay equivalence): a boundary match only stops the
  /// walk when the KEPT PATH is resident — the newest resident
  /// [CompactionRecord]'s `firstKeptEntryId` onwards. The classic
  /// transform keeps records from `firstKeptEntryId` UP TO the compaction
  /// record, and a doubling-block bottom landing between the two (the
  /// normal case on a marathon file) used to stop the walk with the kept
  /// start below the window: `foundFirstKept` stayed false and the
  /// transform silently dropped the whole kept region — records the live
  /// session rendered, half-applying the fold chain at resume. Paging
  /// continues (bounded by one doubling block plus the kept region) until
  /// the kept start is resident; the [tokenBudget] stop is unaffected
  /// (a budget-truncated resume renders the fold-consistent tail, and the
  /// host's boot cap owns the over-window residue). Structured fold
  /// records need no equivalent guard: a fold always references records
  /// OLDER than itself (it is appended after them), so a fold record
  /// inside the window can never target records below it.
  Future<bool> growOlderUntil(
    bool Function(SessionRecord record) found, {
    int maxPages = 512,
    int? tokenBudget,
  }) async {
    _suspendEviction = true;
    try {
      var pages = 0;
      // The walk pages in BLOCKS that double per page (chunk size → 2x →
      // …, capped): each strip is read, decoded and parsed exactly ONCE
      // (SessionChunkReader.readBlockBefore). The capped loadOlder path
      // re-decoded its doubling window on every pass — a 400 MB
      // tail-after-compaction cost 10s+ in redundant decode alone.
      var blockRecords = _chunkRecords;
      var blockBytes = _chunkBytes;
      while (pages < maxPages) {
        final leaf = await getLeafId();
        if (leaf == null) return true; // genuinely empty session
        final branch = await getPathToRoot(leaf);
        if (branch.any(found) && _keptPathResident(branch)) return true;
        if (tokenBudget != null) {
          // Projection-aware whole-branch estimate (issue #503 round 3b):
          // hidden/covered records project as one-line markers or nothing
          // at all, so the raw tally overshot the real context by ~8x on
          // structured-compaction marathons and tripped the budget far
          // too early (under-filled resume window). A whole-branch
          // recompute per page is a chars/4 fold — negligible next to the
          // page's decode — and unlike an incremental prefix tally it
          // sees the hiding markers, which sit LATER on the branch than
          // the records they hide.
          if (estimateProjectedBranchTokens(branch) >= tokenBudget) {
            // gh-968 (AC-R4): the stop fires AFTER a whole doubling block
            // was paged, so accepting the block wholesale overshoots the
            // budget by one BLOCK's tokens — a giant tool result in the
            // last block read the resume tens of thousands of tokens past
            // it (the reported 127%). Trim back to the parity bound: the
            // kept tail overshoots by at most ONE record's tokens.
            _trimTokenBudget(branch, tokenBudget);
            return true;
          }
        }
        if (!_hasOlder) return true; // paged everything
        pages++;
        await _readOlderBlock(blockRecords, blockBytes);
        if (blockRecords < maxWalkBlockRecords) blockRecords *= 2;
        if (blockBytes < maxWalkBlockBytes) blockBytes *= 2;
      }
      return false;
    } finally {
      _suspendEviction = false;
    }
  }

  /// Whether the classic kept path is fully resident on [branch] (gh-1425
  /// AC1): the newest resident [CompactionRecord]'s `firstKeptEntryId` is
  /// resident too. A branch without a compaction record has no kept path
  /// to complete. See [growOlderUntil] for why the boundary stop waits
  /// for this.
  bool _keptPathResident(List<SessionRecord> branch) {
    CompactionRecord? compaction;
    for (final record in branch) {
      if (record is CompactionRecord) compaction = record;
    }
    if (compaction == null) return true;
    final keptId = compaction.firstKeptEntryId;
    if (keptId.isEmpty) return true; // defensive: nothing to wait for
    return branch.any((record) => record.id == keptId);
  }

  /// Largest single block of the [growOlderUntil] walk — the per-page
  /// doubling ceiling (64 MB / 4096 records keeps one page at ~300 ms and
  /// bounds the transient strip buffer).
  static const maxWalkBlockRecords = 4096;
  static const maxWalkBlockBytes = 64 << 20;

  /// Brings the whole file into residency with a sequential forward scan
  /// (gh-1555 W1 — the read-everything trajectory surfaces): strips read
  /// upward from the file head in bounded chunks, every byte read and
  /// parsed exactly once, spliced into the window in ONE prepend.
  /// [growOlderUntil] cannot do this cheaply: its doubling strips answer
  /// "where is the NEARBY boundary", and its per-strip record cap
  /// truncates each strip — a whole-ledger walk under that cap measured
  /// ~13x read+parse amplification on a 30k-record ledger (each 8 MiB
  /// strip kept only its newest few hundred records). A no-op when the
  /// window already reaches the file head.
  ///
  /// gh-1073-honest-degradation pre-check (review): materializing the
  /// whole ledger is the same heap exhaustion the full-open backstop
  /// refuses, so a ledger past [maxWholeLedgerBytes] is refused with the
  /// same `tooLarge` [SessionException] (repair hint included) BEFORE
  /// the scan starts — a clean fast refusal instead of a multi-minute
  /// whole-file scan followed by a probable VM crash. Until AC3a
  /// streaming lands, the merely-large ledger pages in chunked while
  /// the truly-giant one fails honestly.
  Future<void> loadAllOlder({
    int maxBytes = maxWalkBlockBytes,
    int maxWholeLedgerBytes = defaultMaxFullOpenBytes,
  }) async {
    final top = _windowTopOffset;
    if (!_hasOlder || top == null) return;
    final info = await _reader.stat();
    if (info != null && info.size > maxWholeLedgerBytes) {
      throw SessionException(
        'Refusing to page session $_filePath into whole-ledger '
        'residency: ${formatSessionBytes(info.size)} exceeds the '
        '${formatSessionBytes(maxWholeLedgerBytes)} whole-ledger bound. '
        'Shrink the ledger with `fa session repair` — materializing the '
        'whole ledger would exhaust the heap (gh-1073).',
        code: SessionErrorCode.tooLarge,
      );
    }
    final scanned = await _scanFileHeadStrips(top, maxBytes);
    _blockPrepend(scanned.records, scanned.starts, scanned.ends);
    if (scanned.starts.isNotEmpty) _windowTopOffset = scanned.starts.first;
    // The scan ended: either the file head was reached, or the walk
    // broke early on an EMPTY read below `top` — the file was truncated
    // mid-scan (same "empty read ends the walk" convention as
    // [_readOlderBlock]); the window claims full residency either way,
    // but an early-empty read means TRUNCATION, not a clean EOF at the
    // head.
    _hasOlder = false;
    _aboveCount = 0;
  }

  /// The bounded forward scan behind [loadAllOlder]: reads the strips in
  /// `[0, top)` chunk by chunk (every byte read and parsed exactly once)
  /// and returns the new records with their line starts/ends,
  /// oldest-first. Split out of `loadAllOlder` to keep the CRAP ratchet
  /// (CC ≤ 12) — the loop is one cohesive pass.
  Future<({List<SessionRecord> records, List<int> starts, List<int> ends})>
  _scanFileHeadStrips(int top, int maxBytes) async {
    final records = <SessionRecord>[];
    final starts = <int>[];
    final ends = <int>[];
    var offset = 0;
    while (offset < top) {
      final budget = top - offset;
      final chunk = await _reader.readForward(
        offset,
        maxBytes: budget < maxBytes ? budget : maxBytes,
      );
      // An empty read BELOW `top` is not a clean EOF at the head — it
      // means the file was TRUNCATED below the window top mid-scan (the
      // same "empty read ends the walk" convention as [_readOlderBlock]).
      if (chunk.isEmpty) break;
      final entries = chunk.entries;
      for (var i = 0; i < entries.length; i++) {
        final entry = entries[i];
        // The offset-0 line is the session header, not a record
        // (readBlockBefore's contract); anything at/above the window top
        // belongs to the resident window itself; a known id is a
        // straddler from a concurrent append. All three skip classes
        // keep the window lists file-ordered and duplicate-free.
        if (_isScanSkippable(entry, top)) continue;
        records.add(entry.record);
        starts.add(entry.offset);
        ends.add(
          i + 1 < entries.length
              ? entries[i + 1].offset
              : entry.offset + entry.bytes + 1,
        );
      }
      final next = chunk.limitOffset;
      if (next <= offset) break;
      offset = next;
    }
    return (records: records, starts: starts, ends: ends);
  }

  /// One scan-entry skip test (see `_scanFileHeadStrips`): the session
  /// header line, anything at/above the window top, and ids the window
  /// already indexes (a concurrent append's straddler).
  bool _isScanSkippable(SessionChunkEntry entry, int top) {
    return entry.offset == 0 ||
        entry.offset >= top ||
        _byId.containsKey(entry.record.id);
  }

  /// THE window-list block-prepend splice (review): three parallel
  /// `insertAll(0, …)` calls — ONE memmove per list instead of O(window)
  /// per record — plus the per-record re-index (id/offset maps,
  /// `_appendedBelow` reconciliation, label cache). Exactly one copy
  /// exists so the window-list invariant (the three parallel lists kept
  /// in the same file order) cannot drift between two sites when the
  /// layout next changes. Callers: [_indexChunk] (`prepend` — a
  /// loadOlder page) and [loadAllOlder] (the whole-file head scan).
  void _blockPrepend(
    List<SessionRecord> records,
    List<int> starts,
    List<int> ends,
  ) {
    _entries.insertAll(0, records);
    _offsets.insertAll(0, starts);
    _ends.insertAll(0, ends);
    for (var i = 0; i < records.length; i++) {
      final record = records[i];
      _byId[record.id] = record;
      _offsetById[record.id] = starts[i];
      _appendedBelow.remove(record.id);
      updateSessionLabelCache(_labelsById, record);
    }
  }

  /// Record-granular budget trim for the [growOlderUntil] stop (gh-968,
  /// AC-R4): un-indexes the OLDEST resident records down to the cut
  /// [projectedBranchBudgetCut] finds walking the branch from the newest
  /// end backward, so the kept tail's projected estimate stays within
  /// [tokenBudget] — overshoot bounded by one record, never one block.
  ///
  /// The dropped records stay on disk and page back lazily through
  /// [loadOlder]: `_windowTopOffset` rides [_dropOldest] up and
  /// `_hasOlder` is restored when anything was dropped (the walk may have
  /// stopped before any page — a tail window alone over the budget). The
  /// tail anchor (`_branchBottomId`, the leaf) is never touched: the cut
  /// keeps at least the newest record.
  void _trimTokenBudget(List<SessionRecord> branch, int tokenBudget) {
    final cut = projectedBranchBudgetCut(branch, tokenBudget);
    if (cut == null) return; // whole branch fits — defensive, never the stop
    final cutId = branch[cut].id;
    var dropped = 0;
    // The kept cut record is on the branch, hence resident; everything
    // file-older than it (branch records AND interleaved side-branch
    // records) leaves the window.
    while (_entries.isNotEmpty && _entries.first.id != cutId) {
      _dropOldest();
      dropped++;
    }
    if (dropped > 0) _hasOlder = true;
  }

  /// One block page-up for the boundary walk ([growOlderUntil]): a
  /// single-read strip above the window (see
  /// [SessionChunkReader.readBlockBefore]), indexed like a regular chunk.
  /// No branch join here — the walk's predicate reads the index through
  /// [getPathToRoot]; eviction stays suspended by the caller.
  Future<void> _readOlderBlock(int maxRecords, int maxBytes) async {
    final top = _windowTopOffset;
    if (top == null) {
      _hasOlder = false;
      return;
    }
    final chunk = await _reader.readBlockBefore(
      top,
      maxRecords: maxRecords,
      maxBytes: maxBytes,
      // Issue #503 round 3b: the walk crosses hundreds of ~0.75 MB
      // `model_request_summary` ledger payloads that count zero context
      // tokens — decode them header-only (data stubbed to null). The
      // ingest and scrollback paths keep full fidelity; a shallow-parsed
      // record only loses its Request-tab detail, never chain integrity.
      shallowGiantCustoms: true,
    );
    if (chunk.isEmpty) {
      // Mirrors _readOlderChunk: an empty read above the window ends the
      // walk (file top, or a torn region — degenerate, but bounded).
      _hasOlder = false;
      return;
    }
    _windowTopOffset = chunk.firstOffset;
    _hasOlder = chunk.hasOlder;
    _indexChunk(chunk, prepend: true);
    _aboveCount = _aboveCount == null
        ? null
        : _aboveCount! - chunk.entries.length;
  }

  /// One page-up pass: reads the chunk above the window, indexes it
  /// (prepended), advances the window top, and reports the connect id
  /// for the branch join. `null` when no pass applies (no history above,
  /// branch root resident, or the file top reached - `_hasOlder` then
  /// goes false).
  Future<(SessionChunk, String?)?> _readOlderChunk(
    int maxRecords,
    int maxBytes,
  ) async {
    if (!_hasOlder) return null;
    final connectId = await _branchConnectId();
    if (connectId == null) return null; // branch root is already resident
    final top = _windowTopOffset;
    if (top == null) return null;
    final chunk = await _reader.readBefore(
      top,
      maxRecords: maxRecords,
      maxBytes: maxBytes,
    );
    if (chunk.isEmpty) {
      _hasOlder = false;
      return null;
    }
    _windowTopOffset = chunk.firstOffset;
    _hasOlder = chunk.hasOlder;
    _indexChunk(chunk, prepend: true);
    _aboveCount = _aboveCount == null
        ? null
        : _aboveCount! - chunk.entries.length;
    return (chunk, connectId);
  }

  /// Pages one chunk of records back in BELOW the window — the
  /// page-down path after deep paging slid the newest side out.
  /// Returns the records that rejoin the active branch at the bottom,
  /// oldest-first (the transcript delta to append).
  Future<List<SessionRecord>> loadNewer({
    int maxRecords = defaultChunkRecords,
    int maxBytes = defaultChunkBytes,
  }) async {
    final chunk = await _reader.readForward(
      _knownFileBytes,
      maxRecords: maxRecords,
      maxBytes: maxBytes,
    );
    if (chunk.isEmpty) {
      _belowCount = 0;
      return const [];
    }
    _indexChunk(chunk);
    _knownFileBytes = chunk.endOffset;
    if (_belowCount != null) {
      // 0x80000000 == the VM value of `1 << 31`; the shift form is negative
      // on dart2js and would throw inside clamp (issue #1074).
      _belowCount = (_belowCount! - chunk.entries.length).clamp(0, 0x80000000);
    }
    if (chunk.endOffset >= _fileSize) _belowCount = 0;
    final joined = _joinBranchDownward(chunk);
    _evictToBound(newestSide: false);
    return joined;
  }

  /// Re-centers the window on the record at [byteOffset] (issue #135
  /// AC6): the window becomes the chunk around the target, the leaf
  /// stays the true file leaf, and both edge counts reset to unknown
  /// until an edge is walked. Returns the branch records inside the new
  /// window, root-first — the transcript replacement delta. Offsets for
  /// repeat jumps come from [offsetOf] without a re-read.
  Future<List<SessionRecord>> jumpToOffset(
    int byteOffset, {
    int maxRecords = defaultChunkRecords,
    int maxBytes = defaultChunkBytes,
  }) async {
    final info = await _reader.stat();
    if (info == null) return const [];
    _fileSize = info.size;
    _fileMtimeMs = info.mtimeMs;
    if (byteOffset < 0 || byteOffset >= info.size) return const [];
    final chunk = await _reader.readAround(
      byteOffset,
      maxRecords: maxRecords,
      maxBytes: maxBytes,
    );
    if (chunk.isEmpty) return const [];
    _replaceWindowWithChunk(chunk);
    _hasOlder = chunk.hasOlder;
    return _branchWithinChunk(chunk, byteOffset);
  }

  /// Jump-to-record (issue #135 AC6, the mechanism the review asked
  /// for): the offset comes from the sparse map when the record was
  /// ever read this open — [SessionChunkReader.locatePassCount] then
  /// stays flat, the "instant" AC6 jump — and only unexplored records
  /// pay the one-pass [SessionChunkReader.locateRecord] seek. Returns
  /// the re-centered branch (root-first) or an empty list on a miss.
  Future<List<SessionRecord>> jumpToRecord(
    String recordId, {
    int maxRecords = defaultChunkRecords,
    int maxBytes = defaultChunkBytes,
  }) async {
    final offset =
        _offsetById[recordId] ?? await _reader.locateRecord(recordId);
    if (offset == null) return const [];
    return jumpToOffset(offset, maxRecords: maxRecords, maxBytes: maxBytes);
  }

  /// The active branch as currently RESIDENT, root-first — the view
  /// baseline. Bounded by the residency cap by construction (issue
  /// #135 round 4: the app layer must not re-accumulate what the
  /// storage evicted).
  Future<List<SessionRecord>> currentBranch() => _windowBranch();

  /// Streams externally-appended records (a running fa CLI) into the
  /// window. Returns the records that joined the active branch at the
  /// tail, oldest-first — the transcript delta to append — and whether
  /// the window was RE-ANCHORED (the file shrank: truncation or
  /// rotation; issue #135 E5): the delta is then the new window's whole
  /// branch and the caller must replace, not append. While the user is
  /// deep-paged (window bottom above the file tail) appends only
  /// advance the below-count — they page in through [loadNewer].
  Future<({bool reanchored, List<SessionRecord> delta})>
  ingestAppended() async {
    final info = await _reader.stat();
    if (info == null) {
      return (reanchored: false, delta: const <SessionRecord>[]);
    }
    final previousSize = _fileSize;
    if (info.size < previousSize) {
      await _reAnchorToTail();
      return (reanchored: true, delta: await _windowBranch());
    }
    // Same size but the file was REWRITTEN (mtime moved — issue #135
    // AC7): bytes under the window may differ; re-anchor to the tail
    // with the truncation notice rather than trust stale residency.
    if (info.size == previousSize) {
      if (info.mtimeMs != _fileMtimeMs && _fileMtimeMs != 0) {
        await _reAnchorToTail();
        return (reanchored: true, delta: await _windowBranch());
      }
      return (reanchored: false, delta: const <SessionRecord>[]);
    }
    _fileSize = info.size;
    _fileMtimeMs = info.mtimeMs;
    if (_knownFileBytes != previousSize) {
      return _ingestBelowWindow();
    }
    return _ingestAtTail();
  }

  /// Deep-paged ingest: the appended lines land BELOW the window. They
  /// are counted (and their offsets remembered for jumps) without being
  /// indexed - paging down re-reads the range.
  Future<({bool reanchored, List<SessionRecord> delta})>
  _ingestBelowWindow() async {
    final chunk = await _reader.readForward(_knownFileBytes);
    for (final entry in chunk.entries) {
      _offsetById[entry.record.id] = entry.offset;
      _appendedBelow[entry.record.id] = entry.record;
    }
    if (_belowCount != null) {
      _belowCount = _belowCount! + chunk.entries.length;
    }
    return (reanchored: false, delta: const <SessionRecord>[]);
  }

  /// Tail-anchored ingest: the appended lines extend the window bottom
  /// directly. The delta is the part of the branch below the old bottom.
  Future<({bool reanchored, List<SessionRecord> delta})> _ingestAtTail() async {
    final chunk = await _reader.readForward(_knownFileBytes);
    _indexChunk(chunk);
    if (chunk.entries.isNotEmpty) {
      _currentLeafId = leafIdAfterSessionRecord(chunk.entries.last.record);
    }
    _knownFileBytes = chunk.endOffset;
    // Appended lines are new records in the counted total too - a stale
    // memo would drift the banner count downward after every external
    // CLI append.
    if (chunk.entries.isNotEmpty && _totalRecords != null) {
      _totalRecords = _totalRecords! + chunk.entries.length;
    }
    final delta = <SessionRecord>[];
    final path = await getPathToRoot(_currentLeafId);
    final bottomIndex = path.indexWhere((r) => r.id == _branchBottomId);
    if (bottomIndex >= 0) {
      delta.addAll(path.skip(bottomIndex + 1));
      _branchBottomId = path.last.id;
    }
    _evictToBound(newestSide: false);
    return (reanchored: false, delta: delta);
  }

  /// Re-reads the tail after an external truncation: the window resets to
  /// the new file tail.
  Future<void> _reAnchorToTail() async {
    final chunk = await _reader.readTail();
    _fileSize = chunk.fileSize;
    _fileMtimeMs = chunk.fileMtimeMs;
    _totalRecords = null;
    _aboveCount = null;
    _offsetById.clear(); // offsets into the truncated file are garbage
    _replaceWindowWithChunk(chunk);
    // The re-anchored window IS the tail: nothing sits below it. (Set
    // after [_replaceWindowWithChunk], which resets the count to
    // unknown.)
    _belowCount = 0;
    _hasOlder = chunk.hasOlder;
    _currentLeafId = chunk.entries.isEmpty
        ? null
        : leafIdAfterSessionRecord(chunk.entries.last.record);
    _branchBottomId = _currentLeafId;
  }

  /// Re-centers the window on the live tail (issue #1159 E2): a
  /// deep-paged view rejoins the newest records in a bounded number of
  /// reads — one tail re-anchor plus at most two chunk fills back up to
  /// the resident cap (never the chunk-by-chunk page-down crawl) — and
  /// [hasNewer] clears. Returns the re-centered branch (root-first) —
  /// the transcript delta the caller re-projects. A window already at
  /// the tail re-reads the same range (idempotent).
  Future<List<SessionRecord>> jumpToTail() async {
    await _reAnchorToTail();
    // The fill pages up to the resident cap WITHOUT loadOlder's
    // deep-paging eviction running — that eviction drops the NEWEST side
    // and would un-anchor the tail just landed, re-lighting hasNewer into
    // an auto-follow loop (review -Ffw). Overshoot instead trims from
    // the OLD side only, keeping the tail extent pinned.
    _suspendEviction = true;
    try {
      while (_hasOlder &&
          _entries.length < _residentRecordCap &&
          _residentWindowBytes < _residentByteCap) {
        final joined = await loadOlder();
        if (joined.isEmpty) break;
      }
    } finally {
      _suspendEviction = false;
    }
    _evictToBound(newestSide: false);
    return _windowBranch();
  }

  /// The parent id of the oldest branch record in the window — the
  /// connecting record the next [loadOlder] chunk must contain.
  Future<String?> _branchConnectId() async {
    final path = await getPathToRoot(_branchBottomId);
    return path.isEmpty ? null : path.first.parentId;
  }

  /// Records of the freshly-read chunk (above the window) that join the
  /// active branch, root-first: walk parents from the connecting record
  /// ([connectId]) while the chain stays inside the chunk.
  List<SessionRecord> _joinBranchUpward(SessionChunk chunk, String? connectId) {
    if (connectId == null) return const [];
    final byId = {
      for (final entry in chunk.entries) entry.record.id: entry.record,
    };
    final joined = <SessionRecord>[];
    SessionRecord? current = byId[connectId];
    while (current != null) {
      joined.add(current);
      final parentId = current.parentId;
      current = parentId == null ? null : byId[parentId];
    }
    return joined.reversed.toList();
  }

  /// Records of the freshly-read chunk (below the window) that rejoin
  /// the active branch, oldest-first: follow the single-child chain
  /// down from the branch bottom. A fork in the fresh range stops the
  /// walk — the next [loadNewer] (or a jump) resolves it.
  List<SessionRecord> _joinBranchDownward(SessionChunk chunk) {
    final bottom = _branchBottomId;
    if (bottom == null) return const [];
    final childrenByParent = <String, List<SessionRecord>>{};
    for (final entry in chunk.entries) {
      final parentId = entry.record.parentId;
      if (parentId == null) continue;
      childrenByParent.putIfAbsent(parentId, () => []).add(entry.record);
    }
    final joined = <SessionRecord>[];
    var current = bottom;
    while (childrenByParent[current]?.length == 1) {
      final record = childrenByParent[current]!.single;
      joined.add(record);
      _branchBottomId = record.id;
      current = record.id;
    }
    return joined;
  }

  /// The branch records inside a jump chunk around [byteOffset]:
  /// ancestors of the target up to the chunk top, then the single-child
  /// chain down to the chunk bottom. Sets the window's branch bottom.
  List<SessionRecord> _branchWithinChunk(SessionChunk chunk, int byteOffset) {
    var target = chunk.entries.last.record;
    for (final entry in chunk.entries) {
      if (entry.offset <= byteOffset) target = entry.record;
    }
    final byId = {
      for (final entry in chunk.entries) entry.record.id: entry.record,
    };
    final ups = <SessionRecord>[target];
    var walker = target;
    while (walker.parentId != null && byId[walker.parentId!] != null) {
      walker = byId[walker.parentId!]!;
      ups.add(walker);
    }
    final childrenByParent = <String, List<SessionRecord>>{};
    for (final entry in chunk.entries) {
      final parentId = entry.record.parentId;
      if (parentId == null) continue;
      childrenByParent.putIfAbsent(parentId, () => []).add(entry.record);
    }
    final downs = <SessionRecord>[];
    var current = target;
    while (childrenByParent[current.id]?.length == 1) {
      final record = childrenByParent[current.id]!.single;
      downs.add(record);
      current = record;
    }
    _branchBottomId = downs.isEmpty ? target.id : downs.last.id;
    return [...ups.reversed, ...downs];
  }

  /// The active branch as currently resident, root-first (the view
  /// baseline after a truncation re-anchor).
  Future<List<SessionRecord>> _windowBranch() => getPathToRoot(_branchBottomId);

  /// Indexes a chunk's records into the window. [prepend] inserts above
  /// the window (loadOlder); otherwise the chunk extends the bottom.
  void _indexChunk(SessionChunk chunk, {bool prepend = false}) {
    if (chunk.isEmpty) return;
    void add(SessionChunkEntry entry, int end) {
      _offsetById[entry.record.id] = entry.offset;
      if (prepend) {
        _entries.insert(0, entry.record);
        _offsets.insert(0, entry.offset);
        _ends.insert(0, end);
      } else {
        _entries.add(entry.record);
        _offsets.add(entry.offset);
        _ends.add(end);
      }
      _byId[entry.record.id] = entry.record;
      _appendedBelow.remove(entry.record.id);
      updateSessionLabelCache(_labelsById, entry.record);
    }

    // The byte END of entry i: the next entry's start, or for the last
    // entry its own line end — chunk.endOffset is NOT the chunk's end for
    // readAround chunks (it is the file EOF there).
    int endOf(int i) {
      final entry = chunk.entries[i];
      return i + 1 < chunk.entries.length
          ? chunk.entries[i + 1].offset
          : entry.offset + entry.bytes + 1;
    }

    if (prepend) {
      // Block-prepend in ONE insertAll per list — the shared
      // [_blockPrepend] splice (see its doc for the O(n²) history: the
      // per-record insert(0) loop degraded growOlderUntil walks, which
      // run with eviction suspended, to measured ~11x the full open on
      // a 30k-record ledger). Side effects stay per-record in the old
      // loop's newest-first order.
      final n = chunk.entries.length;
      final records = List<SessionRecord>.filled(n, chunk.entries[0].record);
      final starts = List<int>.filled(n, 0);
      final ends = List<int>.filled(n, 0);
      for (var i = 0; i < n; i++) {
        // File order == chunk order; the old per-record insert(0) loop
        // produced exactly this head layout.
        records[i] = chunk.entries[i].record;
        starts[i] = chunk.entries[i].offset;
        ends[i] = endOf(i);
      }
      _blockPrepend(records, starts, ends);
      return;
    }
    for (var i = 0; i < chunk.entries.length; i++) {
      add(chunk.entries[i], endOf(i));
    }
  }

  /// Adds a record to the in-memory index (records that came FROM the
  /// file). Disk-backed appends go through [appendEntry].
  void _indexEntry(
    SessionRecord record, {
    required int start,
    required int end,
  }) {
    _offsetById[record.id] = start;
    _entries.add(record);
    _offsets.add(start);
    _ends.add(end);
    _byId[record.id] = record;
    _appendedBelow.remove(record.id);
    updateSessionLabelCache(_labelsById, record);
  }

  /// Resets the whole window to [chunk] (jump / re-anchor): every
  /// structure is rebuilt, the sparse offset map keeps its history, the
  /// leaf survives.
  void _replaceWindowWithChunk(SessionChunk chunk) {
    _entries.clear();
    _offsets.clear();
    _ends.clear();
    _byId.clear();
    _appendedBelow.clear();
    _labelsById.clear();
    _windowTopOffset = chunk.isEmpty ? null : chunk.firstOffset;
    _knownFileBytes = chunk.entries.isEmpty
        ? chunk.endOffset
        : chunk.entries.last.offset + chunk.entries.last.bytes + 1;
    _aboveCount = null;
    _belowCount = chunk.isEmpty ? 0 : null;
    _indexChunk(chunk);
  }

  /// Slides the window to its bounds. [newestSide] picks WHICH side
  /// gives way — the two directions are the review's core contract:
  ///
  /// - `false` (appends, tail ingests, page-downs): the OLDEST records
  ///   drop. The live tail can never fall out of the window this way,
  ///   and the leaf never moves.
  /// - `true` (deep [loadOlder] paging): the NEWEST records drop. This
  ///   only happens because the user paged up past the cap, and the
  ///   tail side is one [loadNewer] away.
  ///
  /// Every dropped record is pruned from ALL side structures — the
  /// index, the id/label caches — so nothing stays strongly referenced
  /// past residency.
  int _evictToBound({required bool newestSide}) {
    // Suspended during a boundary walk ([growOlderUntil]): the resume
    // pages back to the compaction boundary while keeping the tail
    // anchored — evicting the newest side mid-walk is exactly what slid
    // the leaf out and turned every deep-boundary resume into a full
    // open.
    if (_suspendEviction) return 0;
    var evicted = 0;
    while (_entries.isNotEmpty &&
        (_entries.length > _residentRecordCap ||
            _residentWindowBytes > _residentByteCap)) {
      if (newestSide) {
