    int maxRecords = defaultChunkRecords,
    int maxBytes = defaultChunkBytes,
    bool shallowGiantCustoms = false,
  }) async {
    final info = await stat();
    if (info == null) {
      throw SessionException(
        'Session not found: $path',
        code: SessionErrorCode.notFound,
