  Future<(List<(int, Uint8List)>, bool)> _readStripLines(
    int limit,
    int maxBytes,
  ) async {
    var span = maxBytes;
    while (true) {
      final lo = limit - span > 0 ? limit - span : 0;
      final bytes = await _readRange(lo, limit);
