  /// The records of the active branch (or of the branch ending at
  /// [fromId]), root-first.
  Future<List<SessionRecord>> getBranch({String? fromId}) async {
    final leafId = fromId ?? await _storage.getLeafId();
    return _storage.getPathToRoot(leafId);
  }

